select public.portco_profile_upsert($pp$[{"name":"Alexander & Baldwin","website":"https://alexanderbaldwin.com/","description":"A Hawaiʻi-based owner, operator and developer of high-quality commercial real estate in Hawaiʻi, and the state's largest owner of grocery-anchored neighborhood shopping centers.","sector":"Real estate","subsector":"Commercial real estate (grocery-anchored retail, industrial, office, ground leases)","country":"United States","founded_year":1870,"business_model":"Asset-based (commercial property owner-operator and landlord)","email":"communications@abhi.com","email_type":"press","employees":91,"employees_text":"The Company had 91 employees (including 3 part-time employees) as of December 31, 2025","employees_as_of":"2025-12-31","revenue":206673000,"revenue_currency":"USD","revenue_period":"FY2025","ebitda":118357000,"ebitda_currency":"USD","ebitda_period":"FY2025","ebitda_basis":"derived","leaders":[{"role":"ceo","name":"Lance Parker","title":"President & Chief Executive Officer","source_url":"https://alexanderbaldwin.com/about/leadership/","source_kind":"company","evidence":"Lance Parker President & Chief Executive Officer"},{"role":"cfo","name":"Mark Beers","title":"Senior Vice President, Finance","source_url":"https://alexanderbaldwin.com/about/leadership/","source_kind":"company","evidence":"Mark Beers Senior Vice President, Finance"}],"notes":"Taken private 12 March 2026 by a joint venture of an MW Group affiliate and funds affiliated with Blackstone Real Estate and DivcoWest, at $21.20 per share in cash (enterprise value about $2.3bn including debt); delisted from NYSE (ticker ALEX). The company's leadership page lists no Chief Financial Officer; Mark Beers (SVP, Finance) is the most senior finance title shown. EBITDA is derived: FY2025 operating income $80,019k plus depreciation and amortization $38,338k from the FY2025 10-K; operating income includes $11,685k gain on disposal of assets and settlements.","sources":{"description":{"url":"https://www.prnewswire.com/news-releases/alexander--baldwin-is-taken-private-in-2-3-billion-transaction-302712879.html","name":"PR Newswire (Alexander & Baldwin release)","kind":"wire","as_of":"2026-03-12","evidence":"Alexander & Baldwin (\"A&B\" or the \"Company\"), a Hawaiʻi-based owner, operator and developer of high-quality commercial real estate in Hawaiʻi ... A&B is the state's largest owner of neighborhood shopping centers."},"founded_year":{"url":"https://www.sec.gov/Archives/edgar/data/1545654/000154565426000003/alex-20251231.htm","name":"SEC Form 10-K FY2025","kind":"filing","as_of":"2026-02-27","evidence":"Alexander & Baldwin, Inc. ... is a fully integrated real estate investment trust (\"REIT\") whose history in Hawai‘i dates back to 1870."},"country":{"url":"https://www.sec.gov/Archives/edgar/data/1545654/000154565426000003/alex-20251231.htm","name":"SEC Form 10-K FY2025","kind":"filing","as_of":"2026-02-27","evidence":"a fully integrated real estate investment trust (\"REIT\") headquartered in Honolulu, Hawai‘i"},"business_model":{"url":"https://www.prnewswire.com/news-releases/alexander--baldwin-is-taken-private-in-2-3-billion-transaction-302712879.html","name":"PR Newswire (Alexander & Baldwin release)","kind":"wire","as_of":"2026-03-12","evidence":"The company owns and manages approximately 4.0 million square feet of commercial space in Hawai'i, including 21 retail centers, 14 industrial assets, four office properties, and 146 acres of ground lease holdings."},"email":{"url":"https://alexanderbaldwin.com/contact/","name":"Alexander & Baldwin contact page","kind":"company","as_of":null,"evidence":"Media | Communications Department | Email: communications@abhi.com"},"employees":{"url":"https://www.sec.gov/Archives/edgar/data/1545654/000154565426000003/alex-20251231.htm","name":"SEC Form 10-K FY2025","kind":"filing","as_of":"2025-12-31","evidence":"The Company had 91 employees (including 3 part-time employees) as of December 31, 2025, compared to 99 employees (including 3 part-time employees) in the prior year."},"revenue":{"url":"https://www.sec.gov/Archives/edgar/data/1545654/000154565426000003/alex-20251231.htm","name":"SEC Form 10-K FY2025","kind":"filing","as_of":"2025-12-31","evidence":"CONSOLIDATED STATEMENTS OF OPERATIONS (amounts in thousands) Year Ended December 31, 2025 ... Total operating revenue 206,673"},"ebitda":{"url":"https://www.sec.gov/Archives/edgar/data/1545654/000154565426000003/alex-20251231.htm","name":"SEC Form 10-K FY2025","kind":"filing","as_of":"2025-12-31","evidence":"Operating Income (Loss) 80,019 (statement of operations, 2025); Depreciation and amortization 38,338 (statement of cash flows, 2025); amounts in thousands. Derived: 80,019 + 38,338 = 118,357."}},"holding":{"sponsor":"Blackstone","status":"current","status_note":"Taken private March 2026 by a JV of MW Group, Blackstone Real Estate funds and DivcoWest","asset_class":"Real estate","deal_type":"Take-private","value_creation_plan":"The Investor Group said A&B will retain its name, brand and Honolulu headquarters and continue to be led by a Hawai'i-based team, and that it intends to invest over $100 million across the portfolio to enhance the properties.","value_creation_source_url":"https://www.prnewswire.com/news-releases/alexander--baldwin-to-be-taken-private-in-2-3-billion-transaction-302635840.html","notes":"Announced 8 December 2025; closed 12 March 2026 at an enterprise value of about $2.3bn including debt. Blackstone Real Estate funds are co-owners alongside MW Group and DivcoWest."}},{"name":"Allfleet India","description":"An electric bus operating platform established by PMI Electro, focused on developing, owning and operating large-scale electric public transport fleets through its subsidiaries under long-term concession and service agreements with state transport authorities.","sector":"Transportation","subsector":"Electric bus fleet ownership and operation (public transport concessions)","country":"India","founded_year":2022,"business_model":"B2G (concession-led fleet operator for state transport authorities)","leaders":[{"role":"other","name":"Aanchal Jain","title":"Director, Allfleet (CEO, PMI Electro)","source_url":"https://www.wboc.com/online_features/press_releases/kkr-forms-310-million-strategic-partnership-with-pmi-electro-to-scale-e-bus-platform-allfleet/article_fb07236e-30a0-5901-8c2a-16f54158cdd6.html","source_kind":"wire","evidence":"Aanchal Jain, CEO, PMI Electro and Director, Allfleet , said: “This investment by KKR marks a defining milestone in our journey...”"}],"notes":"Allfleet India Private Limited has no website of its own; the batch domain pmielectro.com belongs to its founder and partner PMI Electro Mobility (an e-bus manufacturer), so it is not recorded as Allfleet's website. The release names no Allfleet CEO or CFO. KKR agreed (16 March 2026) to commit up to $310 million across Allfleet (majority stake) and PMI Electro (minority stake).","sources":{"description":{"url":"https://www.wboc.com/online_features/press_releases/kkr-forms-310-million-strategic-partnership-with-pmi-electro-to-scale-e-bus-platform-allfleet/article_fb07236e-30a0-5901-8c2a-16f54158cdd6.html","name":"Business Wire release (KKR), syndicated","kind":"wire","as_of":"2026-03-16","evidence":"Allfleet is an electric bus operating platform established by PMI Electro, focused on developing, owning and operating large-scale electric public transport fleets through its subsidiaries to deliver services across multiple cities."},"founded_year":{"url":"https://www.wboc.com/online_features/press_releases/kkr-forms-310-million-strategic-partnership-with-pmi-electro-to-scale-e-bus-platform-allfleet/article_fb07236e-30a0-5901-8c2a-16f54158cdd6.html","name":"Business Wire release (KKR), syndicated","kind":"wire","as_of":"2026-03-16","evidence":"Established in 2022, Allfleet (operating through its subsidiaries) is PMI Electro’s e-bus platform, focused on developing, owning, and operating large-scale electric public transport fleets."},"business_model":{"url":"https://www.wboc.com/online_features/press_releases/kkr-forms-310-million-strategic-partnership-with-pmi-electro-to-scale-e-bus-platform-allfleet/article_fb07236e-30a0-5901-8c2a-16f54158cdd6.html","name":"Business Wire release (KKR), syndicated","kind":"wire","as_of":"2026-03-16","evidence":"Allfleet follows a concession-led operating model designed to provide continuity and performance over the lifecycle of public transport assets. ... operating under long-term concession and service agreements with multiple state transport authorities"},"country":{"url":"https://www.wboc.com/online_features/press_releases/kkr-forms-310-million-strategic-partnership-with-pmi-electro-to-scale-e-bus-platform-allfleet/article_fb07236e-30a0-5901-8c2a-16f54158cdd6.html","name":"Business Wire release (KKR), syndicated","kind":"wire","as_of":"2026-03-16","evidence":"This marks KKR’s latest investment in India and first Global Climate Transition investment in the country."}},"holding":{"sponsor":"KKR","status":"current","status_note":"Majority stake agreed March 2026 (up to $310m with a minority stake in PMI Electro); closing expected mid-2026","deal_type":"Buyout","value_creation_plan":"KKR said its investment will support Allfleet's continued growth and strengthen its ability to collaborate with public transport authorities to expand e-bus fleets across key cities, leveraging KKR's global operational expertise; Allfleet is on course to deploy a fleet of more than 5,000 e-buses.","value_creation_source_url":"https://www.wboc.com/online_features/press_releases/kkr-forms-310-million-strategic-partnership-with-pmi-electro-to-scale-e-bus-platform-allfleet/article_fb07236e-30a0-5901-8c2a-16f54158cdd6.html","notes":"Made from KKR's Global Climate Transition strategy (its first such investment in India); the release does not assign an asset class, so none is recorded. Release: businesswire.com/news/home/20260316328702/en/. Deal type: majority stake acquisition."}},{"name":"Atlético de Madrid","website":"https://www.atleticodemadrid.com","description":"Club Atlético de Madrid is one of Europe’s most prestigious football clubs and sporting institutions, playing at the Riyadh Air Metropolitano and developing the ‘Ciudad del Deporte’ sport, leisure and tourism district.","sector":"Sports","subsector":"Professional football club","country":"Spain","founded_year":1903,"leaders":[{"role":"ceo","name":"Miguel Ángel Gil","title":"Chief Executive Officer","source_url":"https://ir.apollo.com/news-events/press-releases/detail/612/apollo-sports-capital-completes-transaction-to-become","source_kind":"sponsor","evidence":"Miguel Ángel Gil and Enrique Cerezo will continue to lead Atlético de Madrid as Chief Executive Officer and Chairman, respectively."},{"role":"other","name":"Enrique Cerezo","title":"Chairman","source_url":"https://ir.apollo.com/news-events/press-releases/detail/612/apollo-sports-capital-completes-transaction-to-become","source_kind":"sponsor","evidence":"Miguel Ángel Gil and Enrique Cerezo will continue to lead Atlético de Madrid as Chief Executive Officer and Chairman, respectively."}],"notes":"Apollo Sports Capital completed its investment to become majority shareholder on 12 March 2026; Quantum Pacific Group remains second-largest shareholder, with Miguel Ángel Gil, Enrique Cerezo and Ares funds remaining shareholders. Shareholders approved up to an additional €100 million of equity and strategic capital. The club's own site (accounts, contacts) blocked automated access, so revenue for 2024-25 is not recorded here.","sources":{"description":{"url":"https://ir.apollo.com/news-events/press-releases/detail/612/apollo-sports-capital-completes-transaction-to-become","name":"Apollo Global Management press release (GlobeNewswire)","kind":"sponsor","as_of":"2026-03-12","evidence":"Club Atlético de Madrid is one of Europe’s most prestigious football clubs and sporting institutions, with a long history of success since its foundation in 1903."},"founded_year":{"url":"https://ir.apollo.com/news-events/press-releases/detail/612/apollo-sports-capital-completes-transaction-to-become","name":"Apollo Global Management press release (GlobeNewswire)","kind":"sponsor","as_of":"2026-03-12","evidence":"with a long history of success since its foundation in 1903"},"country":{"url":"https://ir.apollo.com/news-events/press-releases/detail/612/apollo-sports-capital-completes-transaction-to-become","name":"Apollo Global Management press release (GlobeNewswire)","kind":"sponsor","as_of":"2026-03-12","evidence":"MADRID and NEW YORK, March 12, 2026 (GLOBE NEWSWIRE) -- Atlético de Madrid today announced..."}},"holding":{"sponsor":"Apollo Global Management","status":"current","status_note":"Apollo Sports Capital became majority shareholder in March 2026","asset_class":"Private equity","deal_type":"Buyout","value_creation_plan":"As long-term investors, ASC will partner with Atlético de Madrid’s management to support the Club’s financial strength, sporting competitiveness and community impact; shareholders approved up to an additional €100 million of equity and strategic capital for investment in the teams and in infrastructure projects as part of Ciudad del Deporte.","value_creation_source_url":"https://ir.apollo.com/news-events/press-releases/detail/612/apollo-sports-capital-completes-transaction-to-become","notes":"Apollo describes Atlético as ASC's flagship majority equity investment, not part of a multi-club ownership strategy. Asset class recorded as private equity because the release calls it a majority equity investment; ASC otherwise invests predominantly in credit and hybrid opportunities."}},{"name":"MAI Capital Management","website":"https://www.mai.capital","description":"MAI is a registered investment adviser and wealth management firm unified in purpose to empower clients to simplify, protect, and grow the wealth they have worked so hard to build.","sector":"Financial Services","subsector":"Wealth management / registered investment adviser (RIA)","country":"United States","founded_year":1973,"business_model":"B2C (wealth management for high-net-worth, ultra-high-net-worth and family office clients)","employees":700,"employees_text":"a team of more than 700 people","employees_as_of":"2026-04-30","leaders":[{"role":"ceo","name":"Rick Buoncore","title":"Chairman and CEO","source_url":"https://www.nasdaq.com/press-release/carlyle-completes-acquisition-majority-stake-mai-capital-management-2026-06-08","source_kind":"wire","evidence":"\"Closing this transaction marks the start of something we have been building toward for a long time,” said Rick Buoncore , Chairman and CEO of MAI ."},{"role":"cfo","name":"Philip Noftsinger","title":"Chief Financial Officer","source_url":"https://reports.adviserinfo.sec.gov/reports/ADV/109807/PDF/109807.pdf","source_kind":"filing","evidence":"Form ADV Schedule A (filed 09/18/2026): NOFTSINGER, PHILIP I CHIEF FINANCIAL OFFICER 09/2024"},{"role":"coo","name":"James D. Kacic","title":"Managing Partner and Chief Operating Officer","source_url":"https://reports.adviserinfo.sec.gov/reports/ADV/109807/PDF/109807.pdf","source_kind":"filing","evidence":"Form ADV Schedule A (filed 09/18/2026): KACIC, JAMES, D. I MANAGING PARTNER AND CHIEF OPERATING OFFICER"}],"notes":"SEC-registered adviser, CRD 109807, headquartered at 6050 Oak Tree Blvd, Cleveland, Ohio. Approximately $77.3 billion combined client assets managed or advised as of 30 April 2026 (including affiliate Evoke Advisors). Form ADV Item 5.A reports 562 employees excluding clerical workers for the adviser entity; the 700+ figure is the company's own count for MAI and its affiliated adviser. MAI's website blocked automated access, so no contact email is recorded.","sources":{"description":{"url":"https://www.nasdaq.com/press-release/carlyle-completes-acquisition-majority-stake-mai-capital-management-2026-06-08","name":"Business Wire release (MAI), on Na